        intervals.append((a, b))

    # Check for self-intersections
    # Two semi-circles intersect if and only if one interval is strictly contained within the other.
    # i.e., (a1, b1) and (a2, b2) intersect if a1 < a2 < b2 < b1 or a2 < a1 < b1 < b2.
    # Touching at endpoints (e.g., a1 == a2 or b1 == b2) does not count as intersection.

    has_intersection = False
    for i in range(len(intervals)):
        a1, b1 = intervals[i]
        for j in range(i + 1, len(intervals)):
            a2, b2 = intervals[j]

            # Check strict containment
            if a1 < a2 and a2 < b2 and b2 < b1:
                has_intersection = True
                break
            if a2 < a1 and a1 < b1 and b1 < b2:
                has_intersection = True
                break
        if has_intersection:
            break

    if has_intersection:
        print("yes")
    else:
        print("no")

