import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        x = []
        for _ in range(n):
            x.append(int(next(iterator)))
    except StopIteration:
        return

    if n < 3:
        print("no")
        return

    # Create intervals: (min, max) for each segment connecting x[i] and x[i+1]
    intervals = []
    for i in range(n - 1):
        u, v = x[i], x[i+1]
        if u > v:
            u, v = v, u
        intervals.append((u, v))

    # Check every pair of non-adjacent segments for intersection
    # Two semi-circles intersect if their intervals overlap but neither contains the other.
    # Interval A = [a1, a2], Interval B = [b1, b2] (with a1 < a2, b1 < b2)
    # Overlap condition: max(a1, b1) < min(a2, b2)
    # Containment check: A contains B if a1 <= b1 and b2 <= a2
    # Intersection occurs if they overlap AND (not (A contains B) AND not (B contains A))

    has_intersection = False
    for i in range(len(intervals)):
        for j in range(i + 1, len(intervals)):
            # Skip if segments are adjacent in the sequence (they share an endpoint and cannot intersect elsewhere)
            if abs(i - j) == 1:
                continue

            a1, a2 = intervals[i]
            b1, b2 = intervals[j]

            # Check overlap
            overlap_start = max(a1, b1)
            overlap_end = min(a2, b2)

            if overlap_start < overlap_end:
                # They overlap, now check containment
                a_contains_b = (a1 <= b1) and (b2 <= a2)
                b_contains_a = (b1 <= a1) and (a2 <= b2)

                if not a_contains_b and not b_contains_a:
                    has_intersection = True
                    break
        if has_intersection:
            break

    if has_intersection:
        print("yes")
    else:
        print("no")

if __name__ == "__main__":
    solve()
